//! `fathom completions` — the shell's copy of this grammar, generated by the grammar itself
//! (`e7.4`, **reco-3q4**).
//!
//! A CLI has two other ways to have completions, and both of them lie. The first is a hand-written
//! completion script, which drifts the week a flag is added and then tells a reviewer to type
//! `--episode` into a verb that renamed it. The second is a completion script *generated* by CI into a
//! build directory nobody ships, which is correct and useless. This module is the third way: the
//! scripts and the man pages are rendered here, from [`crate::verbs::command`] — the same
//! [`clap::Command`] `main` parses with — and `tools/gen_shell_artifacts.py` runs this verb to write the
//! committed copies that CI then re-diffs, so the shipped artefact and `--help` cannot disagree.
//!
//! Two properties the generator depends on, and neither is incidental:
//!
//!   * **The grammar does not depend on features.** Every verb exists in every build (ADR-002 §6.1: a
//!     verb compiled out *refuses*, it does not disappear), so one completion script is correct for the
//!     shipped binary and for the `minimal` one. A grammar that hid verbs behind `cfg` would make this
//!     output a function of the build, and the drift check would have to name the feature set too.
//!   * **The output is byte-stable.** No timestamp, no absolute path, no ordering that depends on a hash
//!     map. A generated file that changes when nothing changed is a generated file nobody trusts in a
//!     diff, which is the whole reason roff and shell scripts are committed under `packaging/` instead
//!     of being rebuilt at install time. `clap_mangen`'s date field is deliberately left unset for the
//!     same reason: a man page whose date moves on every render is a man page that is always stale.
//!
//! What a user does with it and what the packager does with it are the same two commands:
//!
//! ```text
//! fathom completions zsh > "$dir/_fathom"
//! fathom completions man --out /usr/local/share/man
//! ```

use std::path::{Path, PathBuf};

use clap::Command;
use clap_complete::Shell;
use eyre::{Result, WrapErr};
use fathom_core::exit::ExitCode;

use crate::verbs::{CompletionsAction, CompletionsManArgs, Pending};

/// The name every generated file is about: the binary, not the crate (ADR-002 §4.3).
const BIN: &str = "fathom";

/// Run `fathom completions`.
pub fn run(action: &CompletionsAction) -> Result<ExitCode> {
    match action {
        CompletionsAction::Bash => print_script(Shell::Bash),
        CompletionsAction::Zsh => print_script(Shell::Zsh),
        CompletionsAction::Fish => print_script(Shell::Fish),
        CompletionsAction::Man(args) => man(args),
    }
}

/// The completion script for one shell, as text.
///
/// `tools/gen_shell_artifacts.py` calls this through the binary rather than linking `clap_complete`
/// itself, so the committed file is exactly what a user can regenerate on their own machine.
pub fn script(shell: Shell) -> Result<String> {
    let mut command = crate::verbs::command();
    let mut buffer: Vec<u8> = Vec::new();
    clap_complete::generate(shell, &mut command, BIN, &mut buffer);
    let text = String::from_utf8(buffer).wrap_err("the completion script was not UTF-8")?;
    if text.trim().is_empty() {
        return Err(Pending::new(
            ExitCode::Error,
            format!("the {shell} completion script came out empty"),
            Some("that is a bug in the generator; `fathom --help` still works".to_owned()),
        )
        .into());
    }
    Ok(text)
}

fn print_script(shell: Shell) -> Result<ExitCode> {
    let text = script(shell)?;
    // One trailing newline, whatever the generator emitted: `fathom completions zsh > _fathom` has to
    // produce the same bytes the committed copy holds, and "the same modulo a blank line" is a drift
    // check that would need a footnote.
    crate::output::line(format_args!("{}", text.trim_end()));
    Ok(ExitCode::Ok)
}

/// One man page, rendered to roff.
///
/// `name` is the page's file name without its section (`fathom`, `fathom-check`), which is also how
/// `man` will be asked for it — git's own convention, and the one that makes a cross-reference inside a
/// page point at a page that exists. A page for `fathom review sign` is `fathom-review-sign.1`, its
/// `NAME` line agrees with its file name, and its `SYNOPSIS` keeps the spaces, because the thing a
/// reader types is `fathom review sign`.
fn render(cmd: &Command, name: &str, source: &str) -> Result<Vec<u8>> {
    let page = cmd
        .clone()
        // `fathom help` is a real clap verb and stays one; it is not a page, and a SUBCOMMANDS section
        // citing `fathom-help(1)` — a page deliberately not written — is a dead link.
        .disable_help_subcommand(true)
        .display_name(name.to_owned())
        .bin_name(name.replace('-', " "));
    let mut buffer: Vec<u8> = Vec::new();
    clap_mangen::Man::new(page)
        .title(name.to_uppercase().replace('-', "_"))
        .section("1")
        // Every page says which version it was cut from, verb pages included: a clone of a subcommand
        // has no version of its own (`clap` propagates one while *building* a parent, which is not what
        // happens here), and the header that would otherwise be written is the bare verb name with an
        // empty version field.
        .source(source.to_owned())
        .render(&mut buffer)
        .wrap_err_with(|| format!("rendering the man page for `{name}`"))?;
    // `Man::render` does not promise a trailing newline, and a roff file that ends mid-line is a file
    // whose next edit is an accident, so settle it here rather than in whoever concatenates next.
    if !buffer.ends_with(b"\n") {
        buffer.push(b'\n');
    }
    Ok(buffer)
}

/// Every page: `fathom.1`, then one per verb, then one per sub-verb (`review sign`, `daemon stop`, …).
///
/// Depth-first, in the order `clap` holds them, which is the order `--help` prints them in: a generated
/// file whose order is arbitrary is a generated file whose diff is noise.
pub fn pages() -> Result<Vec<(String, Vec<u8>)>> {
    let root = crate::verbs::command();
    let source = format!("{BIN} {}", root.get_version().unwrap_or_default());
    let mut out = vec![(BIN.to_owned(), render(&root, BIN, &source)?)];
    let mut queue: Vec<(String, Command)> = verbs_of(&root)
        .map(|sub| (format!("{BIN} {}", sub.get_name()), sub.clone()))
        .collect();
    while let Some((name, command)) = queue.pop() {
        let file = name.replace(' ', "-");
        out.push((file.clone(), render(&command, &file, &source)?));
        let mut children: Vec<(String, Command)> = verbs_of(&command)
            .map(|sub| (format!("{name} {}", sub.get_name()), sub.clone()))
            .collect();
        // Reversed because the queue is a stack, and the order in the list has to stay the order
        // `--help` shows.
        children.reverse();
        queue.extend(children);
    }
    Ok(out)
}

/// The subcommands that deserve a page: not the ones hidden from `--help`, and not clap's own `help`.
fn verbs_of(cmd: &Command) -> impl Iterator<Item = &Command> {
    cmd.get_subcommands()
        .filter(|sub| !sub.is_hide_set() && sub.get_name() != "help")
}

fn man(args: &CompletionsManArgs) -> Result<ExitCode> {
    let all = pages()?;
    let selected: Vec<(String, Vec<u8>)> = match &args.page {
        None => all,
        Some(requested) => {
            let want = requested.trim_end_matches(".1");
            all.into_iter().filter(|(name, _)| name == want).collect()
        }
    };
    let Some((_, first)) = selected.first() else {
        return Err(Pending::usage(
            format!(
                "there is no man page named `{}`",
                args.page.as_deref().unwrap_or("?")
            ),
            "`fathom completions man`, with no --page, prints the page that lists every verb",
        )
        .into());
    };
    match &args.out {
        // No `--out` is the interactive case: `fathom completions man > fathom.1`, or the page for one
        // verb. Dumping fifty pages into a terminal helps nobody.
        None => {
            crate::output::line(format_args!(
                "{}",
                String::from_utf8_lossy(first).trim_end()
            ));
            Ok(ExitCode::Ok)
        }
        Some(dir) => {
            write_pages(Path::new(dir), &selected)?;
            Ok(ExitCode::Ok)
        }
    }
}

/// Write rendered pages under `dir`, in the layout `MANPATH=dir man fathom` expects.
///
/// Returns the paths written, so a caller can name what changed without guessing the layout.
pub fn write_pages(dir: &Path, pages: &[(String, Vec<u8>)]) -> Result<Vec<PathBuf>> {
    let section = dir.join("man1");
    std::fs::create_dir_all(&section)
        .wrap_err_with(|| format!("creating {}", section.display()))?;
    let mut written = Vec::with_capacity(pages.len());
    for (name, body) in pages {
        let path = section.join(format!("{name}.1"));
        write_page(&path, body).wrap_err_with(|| format!("writing {}", path.display()))?;
        written.push(path);
    }
    for path in &written {
        crate::output::line(format_args!("{}", path.display()));
    }
    Ok(written)
}

fn write_page(path: &Path, body: &[u8]) -> Result<()> {
    use std::io::Write;
    let mut file = std::fs::File::create(path)?;
    file.write_all(body)?;
    file.flush()?;
    Ok(())
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used, clippy::expect_used)]

    use super::*;

    /// The grammar must render for every shell it claims to serve, and must be deterministic about it.
    ///
    /// This is the drift check in its smallest form: no filesystem, no second build of the binary, just
    /// the claim "the same command called twice writes the same bytes" — which is the claim every
    /// committed artefact in `packaging/` rests on.
    #[test]
    fn every_shell_renders_the_same_script_twice() {
        for shell in [Shell::Bash, Shell::Zsh, Shell::Fish] {
            let first = script(shell).expect("the script renders");
            let second = script(shell).expect("the script renders twice");
            assert_eq!(
                first, second,
                "{shell}: a generated script moved between runs"
            );
            assert!(
                first.contains("fathom"),
                "{shell}: the script does not name the binary"
            );
        }
    }

    /// One page per verb, named the way `man` will be asked for it, and no page that does not exist.
    #[test]
    fn one_page_per_verb_and_the_names_are_man_names() {
        let pages = pages().expect("the pages render");
        let names: Vec<&str> = pages.iter().map(|(name, _)| name.as_str()).collect();
        assert_eq!(
            names.first().copied(),
            Some(BIN),
            "the first page is always fathom.1"
        );
        assert!(names.contains(&"fathom-check"), "the CI gate has no page");
        assert!(
            names.contains(&"fathom-completions"),
            "this verb has no page"
        );
        assert!(
            names
                .iter()
                .all(|name| !name.contains(' ') && name.starts_with("fathom")),
            "a page name must be a file name and must name this binary: {names:?}"
        );
        // The SUBCOMMANDS sections inside a page cite `<parent>-<child>(1)`; a page named `help` would
        // be a citation to nothing, since clap's own `help` verb is not documented as a page.
        assert!(
            !names.contains(&"fathom-help"),
            "clap's help verb gets no page"
        );
    }

    /// A page must say which version it was cut from — including the verb pages, whose version is not
    /// their own to know.
    #[test]
    fn every_page_names_the_version_it_was_cut_from() {
        let version = crate::features::version_line()
            .split_whitespace()
            .next()
            .unwrap_or_default()
            .to_owned();
        for (name, body) in pages().expect("the pages render") {
            let text = String::from_utf8_lossy(&body);
            assert!(
                text.contains(&format!("fathom {version}")),
                "{name}.1 does not say which version it documents"
            );
        }
    }
}
